STR = {c: {k: v[i] for k, v in _T.items()} for i, c in enumerate(CODES)}
# japonais : parentheses normales (plus lisibles avec toutes les polices)
STR["ja"] = {k: v.replace("（", "(").replace("）", ")") for k, v in STR["ja"].items()}
_lang = "fr"


def default_lang():
    """Langue du systeme si on la gere, sinon l'anglais."""
    code = QLocale.system().name()[:2].lower()
    return code if code in CODES else "en"


def set_lang(code):
    global _lang
    if code in CODES:
        _lang = code


def lang():
    return _lang


def tr(key, **kw):
    s = STR[_lang].get(key) or STR["fr"].get(key) or key
    return s.format(**kw) if kw else s
